SELECT c.c_customer_id, d.d_year, SUM(ws.ws_ext_sales_price) AS total_sales, COUNT(DISTINCT ws.ws_order_number) AS order_cnt, (SELECT d2.d_year FROM date_dim d2 WHERE d2.d_date_sk = ws.ws_ship_date_sk) AS ship_year FROM web_sales ws JOIN customer c ON ws.ws_bill_customer_sk = c.c_customer_sk JOIN web_page wp ON ws.ws_web_page_sk = wp.wp_web_page_sk JOIN date_dim d ON ws.ws_sold_date_sk = d.d_date_sk WHERE wp.wp_type = 'general                                           ' GROUP BY c.c_customer_id, d.d_year, ws.ws_ship_date_sk HAVING SUM(ws.ws_ext_sales_price) > 571.13
